"""Ориентировочная тематическая карта: 4 предмета × 4 класса × 9 месяцев × 4 недели.
Вариативность учительского КТП учтена: это тематические окна, не нормативные даты уроков.
"""
import json, csv, pathlib
BASE=pathlib.Path(__file__).parent
MONTHS=['Сентябрь','Октябрь','Ноябрь','Декабрь','Январь','Февраль','Март','Апрель','Май']
SUBJECTS={'ru':'Русский язык','math':'Математика','world':'Окружающий мир','lit':'Литературное чтение'}
# Формат: 4 тематические недели каждого месяца, для каждой: основная тема ~ дополнительная тема.
D={}
def add(grade,subj,months):
    assert len(months)==9,(grade,subj,len(months))
    res=[]
    for m,raw in enumerate(months):
        parts=[x.strip() for x in raw.split(';')]
        assert len(parts)==4,(grade,subj,MONTHS[m],len(parts))
        for w,p in enumerate(parts,1):
            bits=[x.strip() for x in p.split('~')]
            assert len(bits)==2 and all(bits),(grade,subj,m,w,p)
            idx=m*4+w
            res.append({'month_index':m,'week':w,'slot':idx,'primary':bits[0],'secondary':bits[1]})
    D[f'{grade}_{subj}']=res

